// sw.js — offline engine. GENERATED by tools/build.mjs from sw.template.js.
//
// On install it downloads every app file ONCE, checks each against the
// SHA-256 recorded at build time, and refuses to install if any byte differs.
// After that, Murmur is served entirely from this device — airplane mode works.
//
// Updates: Murmur re-checks sw.js whenever it comes to the front. A changed build
// installs as a NEW cache, verified file by file, then WAITS. The app shows "Restart
// to update" with the new fingerprint; only that tap (or closing every Murmur window)
// lets it take over. Its fingerprint (Settings) will differ — compare with a friend's.

const VERSION = '__VERSION__';
const FILES = __PRECACHE__; // { "./path": "sha256-hex" }
const CACHE = `murmur-${VERSION}`;

const hex = (buf) => [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, '0')).join('');

// Tell open Murmur pages WHY an install failed, so it is never silent.
async function reportInstallError(message) {
  for (const c of await self.clients.matchAll({ includeUncontrolled: true, type: 'window' }))
    c.postMessage({ type: 'murmur-offline-error', message });
}

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    try { await precache(); }
    catch (e) { await reportInstallError(String(e.message || e)); throw e; } // install still fails — on purpose
  })());
});

async function precache() {
  {
    const cache = await caches.open(CACHE);
    for (const [path, want] of Object.entries(FILES)) {
      // Hosts disagree about './index.html': Cloudflare Pages redirects it to './' (pretty URLs),
      // GitHub Pages and Netlify serve it directly. Every host serves the directory URL './',
      // so fetch that. Redirects stay forbidden: a redirect we didn't expect is not trusted.
      const url = path === './index.html' ? './' : path;
      const res = await fetch(url, { cache: 'no-store', credentials: 'omit', redirect: 'error' });
      if (!res.ok) throw new Error(`fetch ${path}: ${res.status}`);
      const body = await res.clone().arrayBuffer();
      const got = hex(await crypto.subtle.digest('SHA-256', body));
      if (got !== want) throw new Error(`integrity check failed for ${path}`); // install aborts; old version stays
      await cache.put(path, res);
    }
  }
}

// The page asks for this only after the person taps "Restart to update", and only a
// worker that already finished install — i.e. passed every integrity check — can be waiting.
self.addEventListener('message', (event) => {
  if (event.data?.type === 'murmur-skip-waiting') self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('murmur-') && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url);
  if (event.request.method !== 'GET' || url.origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const rel = './' + url.pathname.slice(new URL(self.registration.scope).pathname.length);
    const key = event.request.mode === 'navigate' || rel === './' ? './index.html' : rel;
    const hit = await cache.match(key);
    if (hit) return hit;
    try { return await fetch(event.request); }
    catch { return new Response('Offline and not cached', { status: 503, headers: { 'Content-Type': 'text/plain' } }); }
  })());
});
